create or replace function nearby_commute_routes(p_lat double precision,p_lng double precision,p_radius_km double precision default 20) returns table(id uuid,origin_lat double precision,origin_lng double precision,destination_lat double precision,destination_lng double precision,origin_address text,destination_address text,seats_available smallint,price_per_km integer,price_per_unit integer,price_unit text,vehicle_type text,status text,current_lat double precision,current_lng double precision,current_heading double precision,last_location_at timestamptz,distance_km double precision) language sql stable as $$ select c.id,c.origin_lat,c.origin_lng,c.destination_lat,c.destination_lng,c.origin_address,c.destination_address,c.seats_available,c.price_per_km,c.price_per_unit,c.price_unit,c.vehicle_type,c.status,c.current_lat,c.current_lng,c.current_heading,c.last_location_at,(6371*2*asin(sqrt(power(sin(radians(c.current_lat-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(c.current_lat))*power(sin(radians(c.current_lng-p_lng)/2),2)))) as distance_km from commute_routes c where c.status='ACTIVE' and c.seats_available>0 and c.last_location_at>now()-interval '2 minutes' and (6371*2*asin(sqrt(power(sin(radians(c.current_lat-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(c.current_lat))*power(sin(radians(c.current_lng-p_lng)/2),2))))<=least(greatest(p_radius_km,1),50) order by distance_km asc limit 100 $$;